            new Quote { Id = "https://de.wikiquote.org/wiki/Stefan_Zweig", Text = "Der persönliche Kampf zwischen Elisabeth und Maria Stuart, zwischen England und Schottland entscheidet – und darum wird er so bedeutsam – auch zwischen England und Spanien, zwischen Reformation und Gegenreformation.", Author = "Stefan Zweig" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Stefan_Zweig", Text = "Elisabeth, die Realistin, siegt in der Geschichte, Maria Stuart, die Romantikerin, in Dichtung und Legende.", Author = "Stefan Zweig" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Stefan_Zweig", Text = "Keine ihrer eigenen Taten hat Maria Stuart zu solcher legendarischen Figur erhoben wie das unnötig erlittene Unrecht, und keine so sehr Elisabeths moralisches Maß gemindert, als daß sie verabsäumte, in großem Augenblicke wahrhaft großmütig zu sein.", Author = "Stefan Zweig" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Stefan_Zweig", Text = "Maria Stuart hat weniger Angst, zu sterben, als Elisabeth, sie zu töten.", Author = "Stefan Zweig" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Stefan_Zweig", Text = "Nichts hat das deutsche Volk - dies muß immer wieder ins Gedächtnis gerufen werden - so erbittert, so haßwütig, so hitlerreif gemacht wie die Inflation", Author = "Stefan Zweig" },
